@@ -2005,8 +2013,6 @@ static void nft_pipapo_walk(const struct nft_ctx *ctx, struct nft_set *set,
 			goto cont;

 		e = f->mt[r].e;
-		if (nft_set_elem_expired(&e->ext))
-			goto cont;

