+	u64 storage_cookie[MAX_BPF_CGROUP_STORAGE_TYPE];
 	const struct btf_type *attach_func_proto;
 };

diff --git a/kernel/bpf/core.c b/kernel/bpf/core.c
index 9abc37739ca5f..d966e971893ab 100644
